-- WorldBuilding v3 expansion and deterministic legacy consolidation.
CREATE TYPE "BreedGroupId" AS ENUM ('B01', 'B02', 'B03', 'B04', 'B05', 'B06', 'B07', 'B08', 'B09', 'B10', 'B11', 'B12', 'B13', 'B14', 'B15', 'B16', 'B17', 'B18', 'B19', 'B20', 'B21', 'B22', 'B23', 'B24', 'H01', 'H02', 'H03', 'H04', 'H05', 'H06', 'H07', 'H08', 'H09', 'H10', 'H11', 'H12', 'H13', 'H14', 'H15', 'H16', 'H17', 'H18', 'H19', 'H20', 'H21', 'H22', 'H23', 'H24', 'M01', 'M02', 'M03', 'M04', 'M05', 'M06', 'M07', 'M08', 'M09', 'M10', 'M11', 'M12', 'M13', 'M14', 'M15', 'M16', 'M17', 'M18', 'M19', 'M20', 'M21', 'M22', 'M23', 'M24', 'P01', 'P02', 'P03', 'P04', 'P05', 'P06', 'P07', 'P08', 'P09', 'P10', 'P11', 'P12');

ALTER TABLE "Species"
  ADD COLUMN "traitsV3" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
  ADD COLUMN "accentV3" TEXT,
  ADD COLUMN "anthropomorphizationV3" TEXT,
  ADD COLUMN "appearanceV3" TEXT,
  ADD COLUMN "clothingV3" TEXT,
  ADD COLUMN "architectureV3" TEXT,
  ADD COLUMN "originModeV3" "OriginMode" NOT NULL DEFAULT 'UNKNOWN',
  ADD COLUMN "reproductiveMethodV3" "ReproductionMethod" NOT NULL DEFAULT 'UNKNOWN',
  ADD COLUMN "juvenileStagesV3" "JuvenileStage"[] NOT NULL DEFAULT ARRAY[]::"JuvenileStage"[],
  ADD COLUMN "nurseryModeV3" "NurseryMode"[] NOT NULL DEFAULT ARRAY[]::"NurseryMode"[],
  ADD COLUMN "longevityClassV3" "LongevityClass" NOT NULL DEFAULT 'UNKNOWN',
  ADD COLUMN "mortalityModeV3" "NaturalMortalityMode" NOT NULL DEFAULT 'UNKNOWN',
  ADD COLUMN "soulDispositionV3" "SoulDisposition" NOT NULL DEFAULT 'UNKNOWN',
  ADD COLUMN "continuityGroupV3" "ContinuityGroupType" NOT NULL DEFAULT 'UNKNOWN',
  ADD COLUMN "continuityPropagationModeV3" "ContinuityPropagationMode" NOT NULL DEFAULT 'UNKNOWN';
UPDATE "Species" SET
  "appearanceV3" = CASE WHEN cardinality("appearance") = 0 THEN NULL ELSE array_to_string("appearance", '; ') END,
  "anthropomorphizationV3" = CASE WHEN cardinality("anthropomorphization") = 0 THEN NULL ELSE array_to_string("anthropomorphization", '; ') END;

ALTER TABLE "Breed"
  ADD COLUMN "groupIdV3" "BreedGroupId",
  ADD COLUMN "personalityIdV3" TEXT,
  ADD COLUMN "traitsV3" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
  ADD COLUMN "accentV3" TEXT,
  ADD COLUMN "appearanceV3" TEXT,
  ADD COLUMN "clothingV3" TEXT,
  ADD COLUMN "architectureV3" TEXT,
  ADD COLUMN "foodBroadV3" "FoodBroadCategory"[] NOT NULL DEFAULT ARRAY[]::"FoodBroadCategory"[],
  ADD COLUMN "foodSpecificV3" "FoodSpecific"[] NOT NULL DEFAULT ARRAY[]::"FoodSpecific"[],
  ADD COLUMN "terrainBroadV3" "TerrainBroad"[] NOT NULL DEFAULT ARRAY[]::"TerrainBroad"[],
  ADD COLUMN "terrainSpecificV3" "TerrainSpecific"[] NOT NULL DEFAULT ARRAY[]::"TerrainSpecific"[];
UPDATE "Breed" SET
  "appearanceV3" = CASE WHEN cardinality("appearance") = 0 THEN NULL ELSE array_to_string("appearance", '; ') END,
  "accentV3" = CASE WHEN cardinality("accent") = 0 THEN NULL ELSE array_to_string("accent", '; ') END,
  "clothingV3" = CASE WHEN cardinality("costume") = 0 THEN NULL ELSE array_to_string("costume", '; ') END,
  "architectureV3" = CASE WHEN cardinality("architecture") = 0 THEN NULL ELSE array_to_string("architecture", '; ') END;

ALTER TABLE "Culture"
  ADD COLUMN "nameV3" TEXT,
  ADD COLUMN "appearanceV3" TEXT,
  ADD COLUMN "clothingV3" TEXT,
  ADD COLUMN "architectureV3" TEXT;
UPDATE "Culture" SET
  "nameV3" = "cultureName",
  "architectureV3" = NULLIF(concat_ws('; ',
    CASE WHEN btrim("hamletArchitecture") <> '' THEN 'Hamlet: ' || "hamletArchitecture" END,
    CASE WHEN btrim("villageArchitecture") <> '' THEN 'Village: ' || "villageArchitecture" END,
    CASE WHEN btrim("townArchitecture") <> '' THEN 'Town: ' || "townArchitecture" END,
    CASE WHEN btrim("cityArchitecture") <> '' THEN 'City: ' || "cityArchitecture" END,
    CASE WHEN btrim("metropolisArchitecture") <> '' THEN 'Metropolis: ' || "metropolisArchitecture" END,
    CASE WHEN cardinality("architectureColorPalette") > 0 THEN 'Architecture palette: ' || array_to_string("architectureColorPalette", ', ') END
  ), ''),
  "clothingV3" = NULLIF(concat_ws('; ',
    CASE WHEN btrim("clothing") <> '' THEN 'Clothing: ' || "clothing" END,
    CASE WHEN cardinality("clothingPalette") > 0 THEN 'Clothing palette: ' || array_to_string("clothingPalette", ', ') END
  ), '');

ALTER TABLE "Character"
  ADD COLUMN "ageV3" TEXT,
  ADD COLUMN "skinScaleColorV3" TEXT,
  ADD COLUMN "hairFurColorV3" TEXT,
  ADD COLUMN "eyeColorV3" TEXT,
  ADD COLUMN "clothingV3" TEXT;
UPDATE "Character" SET "ageV3" = "age"::TEXT WHERE "age" IS NOT NULL;

ALTER TABLE "PersonalityExpression"
  ADD COLUMN "personalityIdV3" TEXT,
  ADD COLUMN "familyV3" "PersonalityFamily",
  ADD COLUMN "expressionV3" TEXT,
  ADD COLUMN "dominantFactionV3" "Faction"[] NOT NULL DEFAULT ARRAY[]::"Faction"[];
ON CONFLICT ("personalityExpressionId") DO UPDATE SET
  "personalityIdV3" = EXCLUDED."personalityIdV3",
  "familyV3" = EXCLUDED."familyV3",
  "expressionV3" = EXCLUDED."expressionV3",
  "dominantFactionV3" = EXCLUDED."dominantFactionV3"
WHERE "PersonalityExpression"."name" = EXCLUDED."name";
CREATE UNIQUE INDEX "PersonalityExpression_personalityIdV3_key" ON "PersonalityExpression"("personalityIdV3");
